const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(BigInt);
if (input.length < 2) process.exit(0);
let x = input[0];
let n = input[1];

const MOD = 1000000007n;

// fast power mod
function modPow(base, exp, mod) {
    base %= mod;
    let res = 1n;
    while (exp > 0n) {
        if (exp & 1n) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1n;
    }
    return res;
}

// factorize x (x <= 1e9)
function factorize(num) {
    let x = num;
    const primes = [];
    let d = 2n;
    while (d * d <= x) {
        if (x % d === 0n) {
            primes.push(d);
            while (x % d === 0n) x /= d;
        }
        d += (d === 2n ? 1n : 2n); // 2,3,5,7,...
    }
    if (x > 1n) primes.push(x);
    return primes;
}

const primes = factorize(x);
let ans = 1n;

for (const p of primes) {
    // compute exponent: sum_{k>=1} floor(n / p^k)
    let exp = 0n;
    let pk = p;
    while (pk <= n) {
        exp += n / pk;
        // avoid overflow: if pk > n/p break
        if (pk > n / p) break;
        pk *= p;
    }
    if (exp > 0n) {
        ans = (ans * modPow(p % MOD, exp, MOD)) % MOD;
    }
}

console.log(ans.toString());

